async function readAll(table:string):Promise<any[]> {
  const out:any[]=[]
  for(let offset=0;;offset+=1000){const {data,error}=await supabase!.from(table).select('*').range(offset,offset+999);if(error)throw error;out.push(...(data??[]));if(!data||data.length<1000)return out}
}
