 const net=(code:string,currency:string,entityId?:string)=>sum(lines.filter(l=>l.ledger_code===code&&l.currency===currency&&(!entityId||l.entity_id===entityId)).map(l=>Number(l.debit_minor)-Number(l.credit_minor)))
