 async function scanReceipt(file:File){setAttachment(file);setError('');if(!file.type.startsWith('image/')){setScanStatus('File attached. Photo reading works with JPG, PNG and other browser images.');return}if(file.size>15*1024*1024){setError('Photo is over 15 MB. Choose a smaller image.');setAttachment(null);return}setScanStatus('Reading photo on this device...');try{let image:Blob=file;if('createImageBitmap' in window){const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const context=canvas.getContext('2d');if(!context)throw new Error('Image processing is unavailable');context.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();image=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not prepare photo')),'image/jpeg',0.9))}const {createWorker}=await import('tesseract.js');const worker=await createWorker('eng',1,{workerPath:'/ocr/worker.min.js',corePath:'/ocr/core',langPath:'/ocr/lang',logger:event=>setScanStatus(`Reading photo: ${event.status} ${Math.round(event.progress*100)}%`)});try{const result=await worker.recognize(image);setSourceText(result.data.text);applyCapture(result.data.text)}finally{await worker.terminate()}}catch(e){setError(`Could not read this photo: ${message(e)}. You can still attach it and enter the details manually.`);setScanStatus('Photo attached for reference.')}}
 async function saveCurrentDraft(){if(kind!=='expense'&&kind!=='income'){setError('Offline drafts support expenses and income.');return}const draft:EntryDraft={kind,amount,entity,date,category,party,description,reference,entryDue,payment,paidAmount,paymentDate,funding,sourceText,attachment,savedAt:new Date().toISOString()};try{await saveEntryDraft(session.user.id,draft);setSavedDraft(draft);setNotice('Draft saved on this device. Review and post it when online.')}catch(e){setError(`Could not save on this device: ${message(e)}`)}}
 function restoreDraft(draft:EntryDraft){setKind(draft.kind);setAmount(draft.amount);setEntity(draft.entity);setDate(draft.date);setCategory(draft.category);setParty(draft.party);setDescription(draft.description);setReference(draft.reference);setEntryDue(draft.entryDue);setPayment(draft.payment);setPaidAmount(draft.paidAmount);setPaymentDate(draft.paymentDate);setFunding(draft.funding);setSourceText(draft.sourceText);setAttachment(draft.attachment);setTab('Add entry');setNotice('Draft restored. Check the details before posting.')}
 async function postEntry(e:FormEvent){e.preventDefault();await action(async()=>{if(!selectedEntity)throw new Error('Choose an entity.');const cents=minor(amount),isFinancing=financingKinds.includes(kind),pay=split||isFinancing||payment==='unpaid'?0:payment==='partial'?minor(paidAmount):cents;const sig=JSON.stringify(['entry',owner,entity,kind,date,cents,category,subcategory,party,description,reference,pay,paymentDate,funding,entryDue,splitRows]);let data:string|null=null;let postError:Error|null=null;if(split){if(kind!=='expense')throw new Error('Only expenses can use split allocation.');const allocations=splitRows.map(r=>({entity_id:r.entity_id,category:r.category.trim(),amount_minor:minor(r.amount)}));if(sum(allocations.map(r=>r.amount_minor))!==cents)throw new Error('Split amounts must equal the total expense.');const response=await supabase!.rpc('post_split_expense',{p_request_id:requestId(sig),p_owner:owner,p_date:date,p_currency:selectedEntity.currency,p_party:party,p_description:description,p_reference:reference,p_due_date:entryDue||null,p_allocations:allocations});data=response.data;postError=response.error}else if(isFinancing){const response=await supabase!.rpc('post_financing',{p_request_id:requestId(sig),p_owner:owner,p_entity:entity,p_kind:kind,p_date:date,p_amount:cents,p_currency:selectedEntity.currency,p_bank:funding,p_description:description});data=response.data;postError=response.error}else{const response=await supabase!.rpc('post_entry_with_due',{p_request_id:requestId(sig),p_owner:owner,p_entity:entity,p_kind:kind,p_date:date,p_amount:cents,p_currency:selectedEntity.currency,p_category:category,p_subcategory:subcategory,p_party:party,p_description:description,p_reference:reference,p_payment_amount:pay,p_payment_date:pay?paymentDate:null,p_funding_account:pay?funding:null,p_due_date:entryDue||null});data=response.data;postError=response.error}if(postError)throw postError;if(attachment&&data){const path=await upload(attachment);const {error:attachError}=await supabase!.from('ledger_entries').update({attachment_path:path}).eq('id',data);if(attachError)throw attachError}requests.current.delete(sig);if(savedDraft&&savedDraft.amount===amount&&savedDraft.description===description&&savedDraft.date===date&&savedDraft.entity===entity&&savedDraft.kind===kind){await clearEntryDraft(session.user.id);setSavedDraft(null)}setSelected(data??'');setAmount('');setDescription('');setReference('');setEntryDue('');setAttachment(null);setSourceText('');setScanWarnings([]);setScanStatus('');setPayment('unpaid');setPaidAmount('');setSplit(false);setSplitRows([{entity_id:'',category:'',amount:''},{entity_id:'',category:'',amount:''}]);setTab('All entries')},'Entry recorded. Later payments stay linked to it.')}
 async function settle(e:FormEvent){e.preventDefault();if(!entry)return;await action(async()=>{const sig=JSON.stringify(['settle',entry.id,settleAmount,settleDate,settleAccount]);const {error:postError}=await supabase!.rpc('settle_entry',{p_request_id:requestId(sig),p_entry:entry.id,p_amount:minor(settleAmount),p_payment_date:settleDate,p_funding_account:settleAccount,p_reference:null});if(postError)throw postError;requests.current.delete(sig);setSettleAmount('')},'Payment linked to the original entry; no new expense was created.')}
 async function settleSplit(e:FormEvent){e.preventDefault();if(!entry)return;await action(async()=>{const allocations=entryAllocations.filter(a=>a.entry_id===entry.id).map(a=>({allocation_id:a.id,amount_minor:splitSettleAmounts[a.id]?minor(splitSettleAmounts[a.id]):0})).filter(a=>a.amount_minor>0);if(!allocations.length)throw new Error('Enter an amount for at least one allocation.');const sig=JSON.stringify(['split_settle',entry.id,settleDate,settleAccount,allocations]);const {error:postError}=await supabase!.rpc('settle_split_expense',{p_request_id:requestId(sig),p_entry:entry.id,p_date:settleDate,p_funding_account:settleAccount,p_allocations:allocations});if(postError)throw postError;requests.current.delete(sig);setSplitSettleAmounts({})},'Split payment allocated to the original expense without duplicate recognition.')}
 async function settleAmazonNet(e:FormEvent){e.preventDefault();await action(async()=>{const sig=JSON.stringify(['amazon',netIncome,netExpense,netBank,netAmount,netDate]);const {error:postError}=await supabase!.rpc('post_amazon_net_receipt',{p_request_id:requestId(sig),p_income:netIncome,p_expense:netExpense,p_bank:netBank,p_net:minor(netAmount),p_date:netDate});if(postError)throw postError;requests.current.delete(sig);setNetAmount('')},'Gross receivable and existing advertising payable cleared against the net bank deposit.')}
 async function reimburse(e:FormEvent){e.preventDefault();if(!entry)return;await action(async()=>{const sig=JSON.stringify(['reimburse',entry.id,reimburseFrom,reimburseTo,reimburseAmount,reimburseDate]);const {error:postError}=await supabase!.rpc('post_reimbursement',{p_request_id:requestId(sig),p_expense:entry.id,p_from_bank:reimburseFrom,p_to_bank:reimburseTo,p_amount:minor(reimburseAmount),p_date:reimburseDate});if(postError)throw postError;requests.current.delete(sig);setReimburseAmount('')},'Cross-entity due cleared without creating another expense or income.')}
 async function postAdjustment(e:FormEvent){e.preventDefault();if(!entry)return;await action(async()=>{const sig=JSON.stringify(['adjust',entry.id,adjustAction,adjustAmount,adjustDate,adjustAccount]);const {error:postError}=await supabase!.rpc('post_adjustment',{p_request_id:requestId(sig),p_source:entry.id,p_action:adjustAction,p_amount:minor(adjustAmount),p_date:adjustDate,p_account:adjustAccount||null});if(postError)throw postError;requests.current.delete(sig);setAdjustAmount('')},'Linked adjustment posted with an auditable journal, without changing the original entry.')}
 async function createAccount(e:FormEvent){e.preventDefault();await action(async()=>{if(!accountOwnerEntity)throw new Error('Choose an entity.');const sig=JSON.stringify(['account',owner,accountEntity,accountName,accountKind,opening,cutoff,issuer,lastFour,creditLimit]);const {error:postError}=await supabase!.rpc('create_finance_account',{p_request_id:requestId(sig),p_owner:owner,p_entity:accountEntity,p_name:accountName,p_kind:accountKind,p_currency:accountOwnerEntity.currency,p_opening:opening.trim()==='0'?0:minor(opening),p_as_of:cutoff,p_issuer:accountKind==='credit_card'?issuer:null,p_last_four:accountKind==='credit_card'?lastFour:null,p_limit:creditLimit?minor(creditLimit):null});if(postError)throw postError;requests.current.delete(sig);setAccountName('');setOpening('0');setIssuer('');setLastFour('');setCreditLimit('')},'Account created. Opening is separate from historical expenses.')}
 async function transfer(e:FormEvent){e.preventDefault();await action(async()=>{const sig=JSON.stringify(['transfer',source,destination,transferAmount,transferDate]);const {error:postError}=await supabase!.rpc('post_transfer_v2',{p_request_id:requestId(sig),p_source:source,p_destination:destination,p_amount:minor(transferAmount),p_date:transferDate});if(postError)throw postError;requests.current.delete(sig);setTransferAmount('')},'Transfer posted without revenue or expense.')}
 async function repay(e:FormEvent){e.preventDefault();await action(async()=>{const sig=JSON.stringify(['repay',card,bank,repaymentAmount,repaymentDate]);const {error:postError}=await supabase!.rpc('post_card_repayment_v2',{p_request_id:requestId(sig),p_card:card,p_bank:bank,p_amount:minor(repaymentAmount),p_date:repaymentDate});if(postError)throw postError;requests.current.delete(sig);setRepaymentAmount('')},'Card debt reduced. No new expense was created.')}
 async function saveStatement(e:FormEvent){e.preventDefault();await action(async()=>{const account=accounts.find(a=>a.id===statementCard);if(!account)throw new Error('Choose a card.');const {error:saveError}=await supabase!.from('card_statements').insert({owner_id:owner,account_id:account.id,period_start:periodStart,period_end:periodEnd,statement_date:statementDate,due_date:dueDate||null,bill_amount_minor:minor(billAmount),currency:account.currency});if(saveError)throw saveError;setBillAmount('')},'Statement saved as a reference, not additional debt.')}
 async function allocatePayment(e:FormEvent){e.preventDefault();await action(async()=>{const {error:saveError}=await supabase!.rpc('allocate_card_repayment',{p_statement:allocateStatement,p_batch:allocateBatch,p_amount:minor(allocateAmount)});if(saveError)throw saveError;setAllocateAmount('')},'Card repayment allocated to the selected statement.')}
 async function readFile(file:File){setError('');setImportFile(file);setPreview([]);try{const filename=file.name.toLowerCase();if(filename.endsWith('.csv')){const raw=await file.text();setRawText(raw);const parsed=parseCsv(raw);if(parsed.length>10001)throw new Error('This statement has more than 10,000 rows. Split it by statement period before importing.');setPreview(parsed)}else if(filename.endsWith('.xlsx')){const parsed=await readSheet(file);if(parsed.length>10001)throw new Error('This statement has more than 10,000 rows. Split it by statement period before importing.');setPreview(parsed.map(row=>row.map(cell=>cell==null?'':cell instanceof Date?cell.toISOString().slice(0,10):String(cell))));setRawText('XLSX source file preserved in private storage')}else if(filename.endsWith('.pdf')){const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const extracted:string[]=[];for(let p=1;p<=pdf.numPages;p++){const content=await(await pdf.getPage(p)).getTextContent();const groups=new Map<number,{x:number;text:string}[]>();for(const item of content.items){if(!('str'in item)||!('transform'in item))continue;const y=Math.round(Number(item.transform[5])/3)*3;const group=groups.get(y)??[];group.push({x:Number(item.transform[4]),text:String(item.str)});groups.set(y,group)}for(const [,group] of [...groups.entries()].sort((a,b)=>b[0]-a[0]))extracted.push(group.sort((a,b)=>a.x-b.x).map(x=>x.text).join(' ').trim())}const raw=extracted.join('\n');if(raw.replace(/\s/g,'').length<30)throw new Error('This scanned PDF has no readable text. Its rows require manual entry.');setRawText(raw);if(extracted.filter(Boolean).length>10000)throw new Error('This statement has more than 10,000 rows. Split it by statement period before importing.');setPreview([['Posting date','Description','Signed amount'],...extracted.filter(Boolean).map(line=>{const m=line.match(/(\d{4}-\d{2}-\d{2}|\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{4})\s+(.+?)\s+(-?[\d,]+\.\d{2})$/);return m?[m[1],m[2],m[3]]:[line,'','']})])}else throw new Error('Use CSV, XLSX or a text-based PDF.')}catch(e){setError(message(e));setImportFile(null)}}
 async function stageImport(e:FormEvent){e.preventDefault();await action(async()=>{if(!importFile||!importAccount||preview.length<2)throw new Error('Select an account and readable file with transaction rows.');if(!importStart||!importEnd||importEnd<importStart)throw new Error('Enter a valid statement period before staging.');const digest=await crypto.subtle.digest('SHA-256',await importFile.arrayBuffer()),hash=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('');const prior=imports.find(x=>x.account_id===importAccount&&x.file_sha256===hash);if(prior){setSelectedImport(prior.id);throw new Error('This exact file was already imported; no rows were added.')}const currency=accounts.find(a=>a.id===importAccount)?.currency??'INR';const records=preview.slice(1).filter(c=>c.some(Boolean)).map((cells,n)=>({row_ref:String(n+2),posting_date:normalDate(cells[mapDate]??''),description:cells[mapDescription]??'',amount_minor:signedMinor(cells[mapAmount]??''),currency,raw:{cells}}));const filePath=await upload(importFile);const {data:importId,error:importError}=await supabase!.rpc('stage_statement_import',{p_owner:owner,p_account:importAccount,p_file_name:importFile.name,p_file_sha256:hash,p_file_path:filePath,p_period_start:importStart||null,p_period_end:importEnd||null,p_opening:importOpening?signedMinor(importOpening):null,p_closing:importClosing?signedMinor(importClosing):null,p_raw_text:rawText,p_rows:records});if(importError)throw importError;setSelectedImport(importId);setPreview([]);setImportFile(null)},'Statement and source file staged atomically. No journals were posted.')}
 async function saveRow(row:StatementRow){await action(async()=>{const edit=rowEdits[row.id];if(!edit)throw new Error('Edit this row before saving.');const date=normalDate(edit.date),amountValue=signedMinor(edit.amount);const {error:rowError}=await supabase!.from('statement_rows').update({posting_date:date,description:edit.description,amount_minor:amountValue,match_status:date&&amountValue!==null?'unmatched':'needs_review'}).eq('id',row.id);if(rowError)throw rowError},'Statement row mapping updated; raw source remains preserved.')}
 function reviewMissing(row:StatementRow){const source=imports.find(x=>x.id===row.import_id),account=accounts.find(x=>x.id===source?.account_id);if(!account)throw new Error('Statement account not found.');setKind(row.amount_minor&&row.amount_minor>0&&account.kind!=='credit_card'?'income':'expense');setEntity(account.entity_id);setDate(row.purchase_date||row.posting_date||today());setDescription(row.description||'Statement transaction for review');setAmount(row.amount_minor==null?'':(Math.abs(row.amount_minor)/100).toFixed(2));setCategory('');setPayment(account.kind==='credit_card'?'card':'bank');setFunding(account.id);setTab('Add entry');setNotice('Review the category, incurred date and payment method before posting this missing transaction.')}
 async function approve(row:StatementRow){await action(async()=>{const choice=matchChoice[row.id];if(!choice)throw new Error('Select a matching posting.');const {error:matchError}=await supabase!.from('statement_rows').update({match_status:'matched',matched_batch_id:choice}).eq('id',row.id);if(matchError)throw matchError},'Statement row matched to the existing posting.')}
 async function saveInvoice(e:FormEvent){e.preventDefault();await action(async()=>{const curr=entities.find(x=>x.id===invoiceEntity)?.currency;if(!curr)throw new Error('Choose an entity.');const {error:saveError}=await supabase!.from('supplier_invoices').insert({owner_id:owner,entity_id:invoiceEntity,supplier:invoiceSupplier,invoice_number:invoiceNumber,invoice_date:invoiceDate,amount_minor:minor(invoiceAmount),currency:curr});if(saveError)throw saveError;setInvoiceNumber('');setInvoiceAmount('')},'Invoice saved without posting another expense.')}
 async function matchInvoice(e:FormEvent){e.preventDefault();await action(async()=>{const {error:matchError}=await supabase!.from('invoice_matches').insert({owner_id:owner,invoice_id:invoiceId,entry_id:expenseId,allocated_minor:minor(allocation)});if(matchError)throw matchError;setAllocation('')},'Existing expense allocated to invoice without reposting.')}
 async function saveBudget(e:FormEvent){e.preventDefault();await action(async()=>{const curr=entities.find(x=>x.id===budgetEntity)?.currency;if(!curr)throw new Error('Choose an entity.');const {error:saveError}=await supabase!.from('budgets').upsert({owner_id:owner,entity_id:budgetEntity,month:`${budgetMonth}-01`,category:budgetCategory,amount_minor:minor(budgetAmount),currency:curr},{onConflict:'owner_id,entity_id,month,category'});if(saveError)throw saveError;setBudgetAmount('')},'Budget saved.')}
 async function saveCashPlan(e:FormEvent){e.preventDefault();await action(async()=>{const {error:saveError}=await supabase!.from('cash_plan_settings').upsert({owner_id:owner,currency:planCurrency,reserve_minor:nonnegativeMinor(planReserve),essential_costs_30d_minor:nonnegativeMinor(planEssential),confirmed_collections_30d_minor:nonnegativeMinor(planCollections),assumptions:planAssumptions||null},{onConflict:'owner_id,currency'});if(saveError)throw saveError},'Cash plan assumptions saved. Only explicitly confirmed collections are included.')}
 async function saveTimezone(e:FormEvent){e.preventDefault();await action(async()=>{new Intl.DateTimeFormat('en-US',{timeZone:timezone});const {error:saveError}=await supabase!.from('owner_preferences').upsert({owner_id:owner,reporting_timezone:timezone},{onConflict:'owner_id'});if(saveError)throw saveError;setDate(todayIn(timezone));setPaymentDate(todayIn(timezone))},'Reporting timezone saved.')}
 async function openAttachment(path:string){const {data,error:linkError}=await supabase!.storage.from('sakaccounts-private').createSignedUrl(path,60);if(linkError)setError(linkError.message);else window.open(data.signedUrl,'_blank','noopener')}

 if(loading)return <main className="wf-center">Loading your ledger…</main>
 if(offlineOnly)return <main className="wf-offline-page"><div className="wf-quick"><small>SAKACCOUNTS</small><h1>Capture now, post later</h1><p>The connection is offline. Your draft stays on this device until you review and post it online.</p>{error&&<div className="wf-alert error">{error}</div>}{notice&&<div className="wf-alert success">{notice}</div>}{savedDraft&&<div className="wf-draft-banner"><span>Draft saved on this device</span><button className="wf-secondary" onClick={()=>restoreDraft(savedDraft)}>Restore</button><button className="wf-secondary" onClick={()=>void clearEntryDraft(session.user.id).then(()=>setSavedDraft(null))}>Discard</button></div>}<div className="wf-capture-actions"><label className="wf-capture-btn">Take photo<input type="file" accept="image/*" capture="environment" onChange={e=>{const file=e.target.files?.[0];if(file)void scanReceipt(file)}}/></label><label className="wf-capture-btn">Upload receipt<input type="file" accept="image/*,.pdf" onChange={e=>{const file=e.target.files?.[0];if(file)void scanReceipt(file)}}/></label></div>{attachment&&<p>Attached: {attachment.name}</p>}<div className="wf-sms"><label htmlFor="offline-sms">Paste an SMS</label><textarea id="offline-sms" rows={3} value={sourceText} onChange={e=>setSourceText(e.target.value)}/><button className="wf-secondary" onClick={()=>applyCapture(sourceText)}>Fill draft</button></div><div className="wf-quick-form"><Field name="Amount"><input inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field name="Merchant"><input value={party} onChange={e=>{setParty(e.target.value);setDescription(e.target.value)}}/></Field><Field name="Category"><input value={category} onChange={e=>setCategory(e.target.value)}/></Field><Field name="For"><select value={entity} onChange={e=>setEntity(e.target.value)}><option value="">Choose after reconnecting</option>{entities.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field name="Date"><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><button className="wf-primary wf-save" onClick={()=>void saveCurrentDraft()}>Save draft on this device</button></div>{scanStatus&&<p>{scanStatus}</p>}{savedDraft&&<button className="wf-secondary" onClick={()=>restoreDraft(savedDraft)}>Restore saved draft</button>}</div></main>
 if(!owner||!entities.length)return <main className="wf-center"><h1>Setup needs attention</h1><p>{error||'Entities are missing.'}</p><button onClick={()=>void supabase?.auth.signOut()}>Sign out</button></main>
 // Views below keep economic events, actual cash movement, and liabilities distinct.
